// false
// >>> SameChars('eabcdzzzz', 'dddzzzzzzzddddabc')
// false
func SameChars(s0 string, s1 string) bool {
	// Create sets to store unique characters (runes) from each string.
	// Using map[rune]struct{} is the idiomatic way to implement a set in Go.
	set0 := make(map[rune]struct{})
	for _, r := range s0 {
		set0[r] = struct{}{}
	}

	set1 := make(map[rune]struct{})
	for _, r := range s1 {
		set1[r] = struct{}{}
	}

	// If the number of unique characters differs, they cannot have the same set of characters.
	if len(set0) != len(set1) {
		return false
	}

	// Check if every character in the first set exists in the second set.
	for r := range set0 {
		if _, exists := set1[r]; !exists {
			return false
		}
	}

	return true
}
