/*
  Write a function that takes a message, and encodes in such a 
  way that it swaps case of all letters, replaces all vowels in 
  the message with the letter that appears 2 places ahead of that 
  vowel in the english alphabet. 
  Assume only letters. 

  Examples:
  >>> encode('test')
  'TGST'
  >>> encode('This is a message')
  'tHKS KS C MGSSCGG'
  */
const encode = (message) => {
  const vowels = 'aeiouAEIOU';

  return message
    .split('')
    .map((char) => {
      // 1. Swap the case of the character
      let swapped = char === char.toUpperCase() 
        ? char.toLowerCase() 
        : char.toUpperCase();

      // 2. If the original character was a vowel, 
      // shift the swapped character 2 places forward in the alphabet
      if (vowels.includes(char)) {
        swapped = String.fromCharCode(swapped.charCodeAt(0) + 2);
      }

      return swapped;
    })
    .join('');
};

// Test cases
console.log(encode('test'));               // Output: 'TGST'
console.log(encode('This is a message'));  // Output: 'tHKS KS C MGSSCGG'
