// GetRow finds all occurrences of integer x in a 2D slice (nested lists).
// It returns a list of coordinates (row, col) where x is found.
// The results are sorted by row in ascending order and by column in descending order.
func GetRow(lst [][]int, x int) [][2]int {
	var result [][2]int

	// We iterate through the rows in ascending order (0, 1, 2...)
	for i := 0; i < len(lst); i++ {
		// To satisfy the requirement that columns within a row must be in 
		// descending order, we iterate through the columns backwards.
		for j := len(lst[i]) - 1; j >= 0; j-- {
			if lst[i][j] == x {
				result = append(result, [2]int{i, j})
			}
		}
	}

	return result
}

