func Bf(planet1, planet2 string) []string {
	// Define the planets in order of proximity to the Sun
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Find the index of planet1
	idx1 := -1
	for i, p := range planets {
		if p == planet1 {
			idx1 = i
			break
		}
	}

	// Find the index of planet2
	idx2 := -1
	for i, p := range planets {
		if p == planet2 {
			idx2 = i
			break
		}
	}

	// If either planet is not found in the list, return an empty slice
	if idx1 == -1 || idx2 == -1 {
		return []string{}
	}

	// Determine the start and end indices for the slice
	// We need the planets BETWEEN the two, so we use the smaller index + 1 
	// and the larger index as the exclusive upper bound.
	start := idx1
	end := idx2
	if idx2 < idx1 {
		start = idx2
		end = idx1
	}

	// If the planets are adjacent or the same, the range will be empty
	if end-start <= 1 {
		return []string{}
	}

	// Return the slice of planets between the two indices
	return planets[start+1 : end]
}
