		if i%2 == 0 {
			// Calculate Factorial for even i
			fact := 1
			for j := 1; j <= i; j++ {
				fact *= j
			}
			res[i-1] = fact
		} else {
			// Calculate Sum for odd i
			sum := 0
			for j := 1; j <= i; j++ {
				sum += j
			}
			res[i-1] = sum
		}
	}

	return res
