            image = captchaProducer.createImage(captchaStr);
        }

        // 将验证码结果存入redis
        RedisUtils.set(verifyKey, code, RedisConstant.CAPTCHA_CODE_EXPIRE, TimeUnit.SECONDS);

        // 将图像转换为base64字符串
        FastByteArrayOutputStream baos = new FastByteArrayOutputStream();
        try {
            ImageIO.write(image, "jpg", baos);
        } catch (IOException e) {
            throw new TalkTimeException("验证码图像生成失败");
        }
        String base64Image = Base64.encode(baos.toByteArray());

        return LoginAboutAdapt.buildCaptchaVO(base64Image, uuid);
    }

    /**
     * 发送手机验证码
