     * @param phone 手机号
     * @author qingmeng
     * @createTime: 2023/11/11 21:14:04
     */
    @Override
    public void sendPhone(String phone) {
        // 构造发送请求
        SendSmsRequest request = new SendSmsRequest();
        request.setPhoneNumbers(phone);
        request.setSignName("TalkTime");
        request.setTemplateCode("SMS_TEMPLATE_CODE"); // 实际应从配置获取

        // 构造客户端配置
        ClientOverrideConfiguration config = new ClientOverrideConfiguration();
        config.setCredentialsProvider(new StaticCredentialProvider(new Credential(aliAccessKeyId, aliAccessKeySecret)));

        AsyncClient client = new AsyncClient(config);
        try {
            // 生成随机验证码
            String code = String.valueOf((int)((Math.random() * 9 + 1) * 10000));
            // 发送短信
            client.sendSms(request);
            // 存入redis
            RedisUtils.set(RedisConstant.PHONE_CODE_KEY + phone, code, RedisConstant.PHONE_CODE_EXPIRE, TimeUnit.SECONDS);
        } catch (Exception e) {
            throw new TalkTimeException("发送验证码失败");
        }
    }

    /**
     * 注册
     *
     * @param paramDTO 参数对象
     * @param request 请求
     * @author qingmeng
     * @createTime: 2023/11/13 07:51:11
     */
    @Override
    @Transactional
    public void register(RegisterDTO paramDTO, HttpServletRequest request) {
        // 1. 校验手机验证码
        String redisCode = (String) RedisUtils.get(RedisConstant.PHONE_CODE_KEY + paramDTO.getPhone());
        if (StrUtil.isBlank(redisCode) || !redisCode.equals(paramDTO.getPhoneCode())) {
            throw new TalkTimeException("手机验证码错误或已过期");
        }

        // 2. 校验账号是否重复
        SysUser existingUser = sysUserDao.getUserByAccount(paramDTO.getAccount());
        if (existingUser != null) {
            throw new TalkTimeException("该账号已被注册");
        }

        // 3. 构建用户对象
        SysUser sysUser = LoginAboutAdapt.buildRegister(paramDTO);
        // 密码加密
        sysUser.setUserPassword(SaSecureUtil.md5BySalt(paramDTO.getPassword(), SystemConstant.MD5_SALT));

        // 4. 保存用户
        sysUserDao.insert(sysUser);

        // 5. 初始化隐私设置
        SysUserPrivacySetting privacySetting = UserSettingAdapt.buildDefalutSysUserPrivacySetting(sysUser.getId());
        sysUserPrivacySettingDao.insert(privacySetting);

        // 6. 发布注册事件（用于异步处理如发送欢迎消息等）
        applicationEventPublisher.publishEvent(new SysUserRegisterEvent(this, sysUser, request));
    }

